)
from .pricing import price_order

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (files read, min positionals, max positionals)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), 0, 0),
    "low": ((CATALOG, MOVEMENTS), 0, 0),
    "history": ((CATALOG, MOVEMENTS), 1, 1),
    "receive": ((CATALOG, MOVEMENTS), 3, 4),
    "ship": ((CATALOG, MOVEMENTS), 3, 4),
    "quote": ((CATALOG, ORDERS), 1, 1),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), 2, 2),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), 1, 1),
    "report": ((CATALOG, MOVEMENTS, ORDERS), 0, 0),
}
JSON_COMMANDS = ("stock", "low", "history", "quote", "invoice")
TYPED_COMMANDS = ("receive", "ship", "fulfil")
FORMATS = ("text", "csv", "json")

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "  stock [--json] | low [--json] | history SKU [--json]\n"
    "  receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE]\n"
    "  quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json]\n"
    "  report [--format text|csv|json]"
)


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class Unreadable(Exception):
    """A file that cannot be read (exit 2)."""


class Refused(Exception):
    """A mistake in a data file, or a refused request (exit 1)."""


class Args:
    def __init__(self) -> None:
        self.command = ""
        self.directory = "."
        self.positional = []  # type: List[str]
        self.json = False
        self.format = "text"


def parse_args(argv: List[str]) -> Args:
    args = Args()
    rest = []  # type: List[str]
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("option --dir needs a value")
            args.directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            args.directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    if args.directory == "":
        raise UsageError("option --dir needs a value")
    if not rest:
        raise UsageError("no command given")
    args.command = rest[0]
    if args.command not in COMMANDS:
        raise UsageError("unknown command '%s'" % args.command)
    tail = rest[1:]
    if args.command in TYPED_COMMANDS:
        args.positional = tail
    else:
        j = 0
        while j < len(tail):
            arg = tail[j]
            if arg == "--json" and args.command in JSON_COMMANDS:
                args.json = True
            elif args.command == "report" and (arg == "--format" or arg.startswith("--format=")):
                if arg == "--format":
                    if j + 1 >= len(tail):
                        raise UsageError("option --format needs a value")
                    j += 1
                    value = tail[j]
                else:
                    value = arg[len("--format="):]
                if value not in FORMATS:
                    raise UsageError("bad --format value '%s' (use text, csv or json)" % value)
                args.format = value
            elif arg.startswith("-"):
                raise UsageError("unknown option '%s'" % arg)
            else:
                args.positional.append(arg)
            j += 1
    _, low, high = COMMANDS[args.command]
    if not low <= len(args.positional) <= high:
        raise UsageError("wrong number of arguments for '%s'" % args.command)
    if args.command in ("receive", "ship") and parse_date(args.positional[0]) is None:
        raise UsageError("bad date '%s' (use YYYY-MM-DD)" % args.positional[0])
    if args.command == "fulfil" and parse_date(args.positional[1]) is None:
        raise UsageError("bad date '%s' (use YYYY-MM-DD)" % args.positional[1])
    return args


def read_files(directory: str, names: Tuple[str, ...]) -> Dict[str, Optional[bytes]]:
    """Raw bytes of each file; None for a missing movements/orders file."""
    raw = {}  # type: Dict[str, Optional[bytes]]
    for name in names:
        path = os.path.join(directory, name)
        try:
            with open(path, "rb") as handle:
                raw[name] = handle.read()
        except FileNotFoundError:
            if name == CATALOG or not os.path.isdir(directory):
                raise Unreadable("%s: cannot read %s: no such file or directory" % (name, path))
            raw[name] = None
        except OSError as exc:
            raise Unreadable("%s: cannot read %s: %s" % (name, path, exc.strerror or exc))
    return raw


def decode(raw: Dict[str, Optional[bytes]]) -> Dict[str, str]:
    texts = {}
    for name, data in raw.items():
        if data is None:
            texts[name] = ""
            continue
        try:
            texts[name] = data.decode("utf-8")
        except UnicodeDecodeError:
            raise Unreadable("%s: not valid UTF-8" % name)
    return texts


class Data:
    def __init__(self, args: Args) -> None:
        names = COMMANDS[args.command][0]
        self.directory = args.directory
        self.raw = read_files(args.directory, names)
        self.text = decode(self.raw)
        self.catalog = self._parse(CATALOG, lambda t: parse_catalog(t))
        self.movements = []  # type: list
        self.orders = []  # type: List[Order]
        if MOVEMENTS in self.text:
            self.movements = self._parse(MOVEMENTS, lambda t: parse_movements(t, self.catalog))
        if ORDERS in self.text:
            self.orders = self._parse(ORDERS, lambda t: parse_orders(t, self.catalog))

    def _parse(self, name, parser):
        try:
            return parser(self.text[name])
        except ParseError as exc:
            raise Refused("%s: %s" % (name, exc))

    def find_order(self, ident: str) -> Order:
        wanted = upper(ident)
        for order in self.orders:
            if order.id == wanted:
                return order
        raise Refused("unknown order '%s'" % ident)

    def append_movements(self, lines: List[str]) -> None:
        """Validate the file with ``lines`` added, then append them."""
        raw = self.raw.get(MOVEMENTS)
        prefix = "\n" if raw and not raw.endswith(b"\n") else ""
        addition = prefix + "".join(line + "\n" for line in lines)
        self._parse_movements_text(self.text[MOVEMENTS] + addition)
        path = os.path.join(self.directory, MOVEMENTS)
        try:
            with open(path, "ab") as handle:
                handle.write(addition.encode("utf-8"))
        except OSError as exc:
            raise Unreadable("%s: cannot write %s: %s" % (MOVEMENTS, path, exc.strerror or exc))

    def _parse_movements_text(self, text: str) -> None:
        try:
            parse_movements(text, self.catalog)
        except ParseError as exc:
            raise Refused("%s: %s" % (MOVEMENTS, exc))


# ---------------------------------------------------------------- formatting


def money(value) -> str:
    return format(value, "f")


def dump(obj) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


def quote_text(header: str, quote: Quote) -> str:
    out = [header]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (line.sku, line.quantity, money(line.unit), money(line.gross),
               money(line.discount), money(line.net))
        )
    out.append("subtotal " + money(quote.subtotal))
    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return lines_out(out)


def quote_json(order: Order, quote: Quote) -> str:
    return dump(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": money(l.unit),
                    "gross": money(l.gross),
                    "discount": money(l.discount),
                    "net": money(l.net),
                }
                for l in quote.lines
            ],
            "subtotal": money(quote.subtotal),
            "order_discount": money(quote.order_discount),
            "tax": money(quote.tax),
            "total": money(quote.total),
        }
    )


def header(order: Order, prefix: str = "") -> str:
    return "%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)


# ------------------------------------------------------------------ commands


def cmd_stock(args: Args, data: Data) -> str:
    rows = shelves.stock_rows(data.catalog, data.movements)
    if args.json:
        return dump([r._asdict() for r in rows])
    return lines_out(["%s %d %s %s" % (r.sku, r.onhand, r.status, r.name) for r in rows])


def cmd_low(args: Args, data: Data) -> str:
    rows = shelves.low_rows(data.catalog, data.movements)
    if args.json:
        return dump([r._asdict() for r in rows])
    return lines_out(["%s %d %d %d" % r for r in rows])


def _known_sku(text: str, data: Data) -> str:
    sku = upper(text)
    if not is_sku(text) or sku not in data.catalog:
        raise Refused("unknown SKU '%s'" % text)
    return sku


def cmd_history(args: Args, data: Data) -> str:
    sku = _known_sku(args.positional[0], data)
    rows = shelves.history_rows(sku, data.movements)
    if args.json:
        return dump([r._asdict() for r in rows])
    return lines_out(
        [("%s %s %d %s" % r).rstrip(" ") if not r.note else "%s %s %d %s" % r for r in rows]
    )


def _move(args: Args, data: Data) -> str:
    when, sku_text, qty_text = args.positional[:3]
    note = args.positional[3].strip(" \t") if len(args.positional) == 4 else ""
    sku = _known_sku(sku_text, data)
    quantity = parse_uint(qty_text)
    if quantity is None or quantity < 1:
        raise Refused("bad quantity '%s' (a whole number of one or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    sign = "+" if args.command == "receive" else "-"
    line = "%s %s %s%d" % (when, sku, sign, quantity)
    if note:
        line += " " + note
    data.append_movements([line])
    return line + "\n"


def cmd_quote(args: Args, data: Data) -> str:
    order = data.find_order(args.positional[0])
    quote = price_order(order, data.catalog)
    if args.json:
        return quote_json(order, quote)
    return quote_text(header(order), quote)


def cmd_fulfil(args: Args, data: Data) -> str:
    order = data.find_order(args.positional[0])
    when = parse_date(args.positional[1])
    if when < order.date:
        raise Refused(
            "cannot fulfil %s on %s: before the order date %s"
            % (order.id, when.isoformat(), order.date.isoformat())
        )
    plan = orders_mod.plan_fulfil(order, when, data.movements)
    new_lines = ["%s %s -%d order %s" % (when.isoformat(), sku, n, order.id) for sku, n in plan if n > 0]
    if new_lines:
        data.append_movements(new_lines)
    shipped = orders_mod.shipped_so_far(order, data.movements)
    out = []
    for sku, n in plan:
        shipped[sku] += n
        owed = dict(order.lines)[sku] - shipped[sku]
        out.append("%s shipped %d backordered %d" % (sku, n, owed))
    out.append("status " + orders_mod.order_status(order, shipped))
    return lines_out(out)


def cmd_invoice(args: Args, data: Data) -> str:
    order = data.find_order(args.positional[0])
    quote = orders_mod.invoice_quote(order, data.catalog, data.movements)
    if quote is None:
        raise Refused("nothing has shipped for %s" % order.id)
    if args.json:
        return quote_json(order, quote)
    return quote_text(header(order, "invoice "), quote)


REPORT_KEYS = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]


def cmd_report(args: Args, data: Data) -> str:
    rows = orders_mod.report_rows(data.orders, data.catalog, data.movements)
    for row in rows:
        row["quoted"] = money(row["quoted"])
        row["invoiced"] = money(row["invoiced"])
    if args.format == "json":
        return dump(rows)
    if args.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(REPORT_KEYS)
        for row in rows:
            writer.writerow([row[k] for k in REPORT_KEYS])
        return buffer.getvalue()
    return lines_out(
        [
            "%s %s %s %s %d/%d %s %s"
            % (r["order"], r["date"], r["customer"], r["status"], r["shipped"],
               r["ordered"], r["quoted"], r["invoiced"])
            for r in rows
        ]
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": _move,
    "ship": _move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ---------------------------------------------------------------------- main


def _write(stream, text: str) -> None:
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8", "replace"))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _fail(message: str, usage: bool = False) -> None:
    text = "stockroom: %s\n" % message
    if usage:
        text += USAGE + "\n"
    try:
        _write(sys.stderr, text)
    except (OSError, ValueError):
        pass


def _quiet_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parse_args(list(argv))
        data = Data(args)
        output = HANDLERS[args.command](args, data)
    except UsageError as exc:
        _fail(str(exc), usage=True)
        return 2
    except Unreadable as exc:
        _fail(str(exc))
        return 2
    except Refused as exc:
        _fail(str(exc))
        return 1
    try:
        _write(sys.stdout, output)
    except BrokenPipeError:
        _quiet_stdout()
    return 0
