    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return lines_out(out)


def quote_json(order: Order, quote: Quote) -> str:
    return dump(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": money(l.unit),
                    "gross": money(l.gross),
                    "discount": money(l.discount),
                    "net": money(l.net),
                }
                for l in quote.lines
            ],
            "subtotal": money(quote.subtotal),
            "order_discount": money(quote.order_discount),
            "tax": money(quote.tax),
            "total": money(quote.total),
        }
    )


def header(order: Order, prefix: str = "") -> str:
    return "%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)


# ------------------------------------------------------------------ commands


def cmd_stock(args: Args, data: Data) -> str:
    rows = shelves.stock_rows(data.catalog, data.movements)
    if args.json:
        return dump([r._asdict() for r in rows])
    return lines_out(["%s %d %s %s" % (r.sku, r.onhand, r.status, r.name) for r in rows])


def cmd_low(args: Args, data: Data) -> str:
    rows = shelves.low_rows(data.catalog, data.movements)
    if args.json:
        return dump([r._asdict() for r in rows])
    return lines_out(["%s %d %d %d" % r for r in rows])


def _known_sku(text: str, data: Data) -> str:
    sku = upper(text)
    if not is_sku(text) or sku not in data.catalog:
        raise Refused("unknown SKU '%s'" % text)
    return sku


def cmd_history(args: Args, data: Data) -> str:
    sku = _known_sku(args.positional[0], data)
    rows = shelves.history_rows(sku, data.movements)
    if args.json:
        return dump([r._asdict() for r in rows])
    return lines_out(
        [("%s %s %d %s" % r).rstrip(" ") if not r.note else "%s %s %d %s" % r for r in rows]
    )


def _move(args: Args, data: Data) -> str:
    when, sku_text, qty_text = args.positional[:3]
    note = args.positional[3].strip(" \t") if len(args.positional) == 4 else ""
    sku = _known_sku(sku_text, data)
    quantity = parse_uint(qty_text)
    if quantity is None or quantity < 1:
        raise Refused("bad quantity '%s' (a whole number of one or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    sign = "+" if args.command == "receive" else "-"
    line = "%s %s %s%d" % (when, sku, sign, quantity)
    if note:
        line += " " + note
    data.append_movements([line])
    return line + "\n"


def cmd_quote(args: Args, data: Data) -> str:
    order = data.find_order(args.positional[0])
    quote = price_order(order, data.catalog)
    if args.json:
        return quote_json(order, quote)
    return quote_text(header(order), quote)


def cmd_fulfil(args: Args, data: Data) -> str:
    order = data.find_order(args.positional[0])
    when = parse_date(args.positional[1])
    if when < order.date:
        raise Refused(
            "cannot fulfil %s on %s: before the order date %s"
            % (order.id, when.isoformat(), order.date.isoformat())
        )
    plan = orders_mod.plan_fulfil(order, when, data.movements)
    new_lines = ["%s %s -%d order %s" % (when.isoformat(), sku, n, order.id) for sku, n in plan if n > 0]
    if new_lines:
        data.append_movements(new_lines)
    shipped = orders_mod.shipped_so_far(order, data.movements)
    out = []
    for sku, n in plan:
        shipped[sku] += n
        owed = dict(order.lines)[sku] - shipped[sku]
        out.append("%s shipped %d backordered %d" % (sku, n, owed))
    out.append("status " + orders_mod.order_status(order, shipped))
    return lines_out(out)


def cmd_invoice(args: Args, data: Data) -> str:
    order = data.find_order(args.positional[0])
    quote = orders_mod.invoice_quote(order, data.catalog, data.movements)
    if quote is None:
        raise Refused("nothing has shipped for %s" % order.id)
    if args.json:
        return quote_json(order, quote)
    return quote_text(header(order, "invoice "), quote)


REPORT_KEYS = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]


def cmd_report(args: Args, data: Data) -> str:
    rows = orders_mod.report_rows(data.orders, data.catalog, data.movements)
    for row in rows:
        row["quoted"] = money(row["quoted"])
        row["invoiced"] = money(row["invoiced"])
    if args.format == "json":
        return dump(rows)
    if args.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(REPORT_KEYS)
        for row in rows:
            writer.writerow([row[k] for k in REPORT_KEYS])
        return buffer.getvalue()
    return lines_out(
        [
            "%s %s %s %s %d/%d %s %s"
            % (r["order"], r["date"], r["customer"], r["status"], r["shipped"],
               r["ordered"], r["quoted"], r["invoiced"])
            for r in rows
        ]
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": _move,
    "ship": _move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ---------------------------------------------------------------------- main


def _write(stream, text: str) -> None:
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8", "replace"))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _fail(message: str, usage: bool = False) -> None:
    text = "stockroom: %s\n" % message
    if usage:
        text += USAGE + "\n"
    try:
        _write(sys.stderr, text)
    except (OSError, ValueError):
        pass


def _quiet_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parse_args(list(argv))
        data = Data(args)
        output = HANDLERS[args.command](args, data)
    except UsageError as exc:
        _fail(str(exc), usage=True)
        return 2
    except Unreadable as exc:
        _fail(str(exc))
        return 2
    except Refused as exc:
        _fail(str(exc))
        return 1
    try:
        _write(sys.stdout, output)
    except BrokenPipeError:
        _quiet_stdout()
    return 0
